//! LMS/HSS known-answer fixtures and case runner for the SHA-65 tests.
//!
//! The fixtures under `fixtures/` are generated by `scripts/gen_lms_vectors.py` from
//! RFC 8554 Appendix F, the NIST ACVP LMS sigVer vectors and signatures made by the
//! pinned independent signer `hsslms 0.1.3` (see `fixtures/MANIFEST.json`). This crate
//! parses them without allocation or panics and runs each case under three policies:
//!
//! - [`keelsign_verify::verify_pq`], the device path under the default
//!   [`ParameterPolicy::keelsign_default`] (at most two HSS levels);
//! - [`keelsign_verify::verify_pq_with`] with
//!   [`DefaultBackend::cnsa_2_0`](keelsign_verify::DefaultBackend::cnsa_2_0), the strict
//!   device path under [`ParameterPolicy::cnsa_2_0`] (single tree, `L = 1`);
//! - [`keelsign_verify::lms::verify_with_policy`] with
//!   [`ParameterPolicy::rfc_8554_all_sets`] (host and test use only),
//!
//! so the same code runs in the host KATs and on the boards.
//!
//! Fixture format "KSLM v2" (lengths little-endian):
//!
//! ```text
//! header:   b"KSLM", u16 version (2), u16 case count
//! per case: u16 id, u8 source (0 = rfc8554, 1 = acvp, 2 = hsslms),
//!           u8 expect_default, u8 expect_cnsa_2_0, u8 expect_rfc_all_sets,
//!           u16 pk_len, u16 sig_len, u16 msg_len, then pk, sig and msg bytes
//! expectation codes: 0 SignatureInvalid, 1 Ok, 2 UnsupportedParameterSet,
//!                    3 MalformedSignature, 4 InvalidPublicKey
//! ```
#![no_std]
#![forbid(unsafe_code)]

pub use keelsign_verify::Error;

use keelsign_verify::lms::{self, ParameterPolicy};
use keelsign_verify::tlv::{TLV_KEELSIGN_KEY_ID, TLV_LMS_HSS_SIG};
use keelsign_verify::{
    Algorithm, DefaultBackend, TrustedKey, TrustedKeys, key_id_of, verify_pq, verify_pq_with,
};

/// Fixture magic bytes.
pub const MAGIC: [u8; 4] = *b"KSLM";

/// Fixture format version.
pub const VERSION: u16 = 2;

/// On-target fixture: RFC 8554 Test Cases 1 and 2, one ACVP SHA-256/192 case, hsslms
/// M32 L2, M24 L1 and L2, rotation keys A and B, W4 and L=3, one tampered and one
/// trailing-byte case.
pub const LMS_TARGET: &[u8] = include_bytes!("../fixtures/lms-target.bin");

/// Cases in [`LMS_TARGET`].
pub const TARGET_CASES: u32 = 14;

