/// Where a case comes from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Source {
    /// RFC 8554 Appendix F (and cases derived from Test Case 1).
    Rfc8554,
    /// NIST ACVP-Server LMS sigVer (SHA-256/192, W1 and W2).
    Acvp,
    /// Signed by the pinned independent signer hsslms 0.1.3.
    Hsslms,
}

impl Source {
    /// Short name used in logs.
    pub const fn name(self) -> &'static str {
        match self {
            Source::Rfc8554 => "rfc8554",
            Source::Acvp => "acvp",
            Source::Hsslms => "hsslms",
        }
    }
}

/// The expected result of a verification.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Expect {
    /// `Err(Error::SignatureInvalid)`.
    SignatureInvalid,
    /// `Ok(())`.
    Ok,
    /// `Err(Error::UnsupportedParameterSet)`.
    UnsupportedParameterSet,
    /// `Err(Error::MalformedSignature)`.
    MalformedSignature,
    /// `Err(Error::InvalidPublicKey)`.
    InvalidPublicKey,
}

impl Expect {
    /// The expectation with fixture code `code`.
    pub const fn from_code(code: u8) -> Option<Self> {
        match code {
            0 => Some(Expect::SignatureInvalid),
            1 => Some(Expect::Ok),
            2 => Some(Expect::UnsupportedParameterSet),
            3 => Some(Expect::MalformedSignature),
            4 => Some(Expect::InvalidPublicKey),
            _ => None,
        }
    }

    /// The verification result this expectation stands for.
    pub const fn result(self) -> Result<(), Error> {
        match self {
            Expect::SignatureInvalid => Err(Error::SignatureInvalid),
            Expect::Ok => Ok(()),
            Expect::UnsupportedParameterSet => Err(Error::UnsupportedParameterSet),
            Expect::MalformedSignature => Err(Error::MalformedSignature),
            Expect::InvalidPublicKey => Err(Error::InvalidPublicKey),
        }
    }
}

/// A short name for a verification result, for logs (defmt cannot format [`Error`]).
pub fn result_name(result: Result<(), Error>) -> &'static str {
    match result {
        Ok(()) => "Ok",
        Err(Error::SignatureInvalid) => "SignatureInvalid",
        Err(Error::UnsupportedParameterSet) => "UnsupportedParameterSet",
        Err(Error::MalformedSignature) => "MalformedSignature",
        Err(Error::InvalidPublicKey) => "InvalidPublicKey",
        Err(Error::KeyNotTrusted) => "KeyNotTrusted",
        Err(Error::UnsupportedAlgorithm(_)) => "UnsupportedAlgorithm",
        Err(_) => "OtherError",
    }
}

/// Why a fixture could not be parsed.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ParseError {
    /// The fixture does not start with [`MAGIC`].
    BadMagic,
    /// The header names a format version other than [`VERSION`].
    UnsupportedVersion(u16),
    /// A case has a source byte other than 0, 1 or 2.
    UnknownSource(u8),
    /// A case has an expectation code other than 0..=4.
    BadExpectation(u8),
    /// The input ends inside a header or a case.
    Truncated,
    /// Bytes remain after the declared number of cases.
    TrailingBytes,
}

/// One known-answer case, borrowing its bytes from the fixture.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Case<'a> {
    pub id: u16,
    pub source: Source,
    /// Expected result of [`verify_case`] (device path, `keelsign_default()`).
    pub expect_default: Expect,
    /// Expected result of [`verify_case_cnsa_2_0`] (strict device path, `cnsa_2_0()`).
    pub expect_cnsa_2_0: Expect,
    /// Expected result of [`verify_case_rfc_all_sets`].
    pub expect_rfc_all_sets: Expect,
    pub pk: &'a [u8],
    pub sig: &'a [u8],
    pub msg: &'a [u8],
}

/// A parsed fixture header plus the undecoded case bytes.
#[derive(Clone, Copy, Debug)]
pub struct Fixture<'a> {
    pub count: u16,
    body: &'a [u8],
}

impl<'a> Fixture<'a> {
    /// Parses the fixture header. The cases are decoded lazily by [`Fixture::cases`].
    pub fn parse(bytes: &'a [u8]) -> Result<Self, ParseError> {
        let mut rest = bytes;
        if take(&mut rest, MAGIC.len())? != MAGIC.as_slice() {
            return Err(ParseError::BadMagic);
        }
        let version = read_u16(&mut rest)?;
        if version != VERSION {
            return Err(ParseError::UnsupportedVersion(version));
        }
        let count = read_u16(&mut rest)?;
        Ok(Self { count, body: rest })
    }

    /// Iterates over the cases. After the first error the iterator ends.
    pub fn cases(&self) -> Cases<'a> {
        Cases {
            rest: self.body,
            remaining: self.count,
            done: false,
        }
    }

    /// The case with ID `id`, if the fixture parses up to it.
    pub fn case(&self, id: u16) -> Option<Case<'a>> {
        self.cases().map_while(Result::ok).find(|c| c.id == id)
    }
}

/// Iterator over the cases of a [`Fixture`].
#[derive(Clone, Debug)]
pub struct Cases<'a> {
    rest: &'a [u8],
    remaining: u16,
    done: bool,
}

impl<'a> Iterator for Cases<'a> {
    type Item = Result<Case<'a>, ParseError>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.done {
            return None;
        }
        if self.remaining == 0 {
            self.done = true;
            return (!self.rest.is_empty()).then_some(Err(ParseError::TrailingBytes));
        }
        self.remaining -= 1;
        let case = parse_case(&mut self.rest);
        if case.is_err() {
            self.done = true;
        }
        Some(case)
    }
}

fn parse_case<'a>(rest: &mut &'a [u8]) -> Result<Case<'a>, ParseError> {
    let id = read_u16(rest)?;
    let source = match read_u8(rest)? {
        0 => Source::Rfc8554,
        1 => Source::Acvp,
        2 => Source::Hsslms,
        other => return Err(ParseError::UnknownSource(other)),
    };
    let expect = |code: u8| Expect::from_code(code).ok_or(ParseError::BadExpectation(code));
    let expect_default = expect(read_u8(rest)?)?;
    let expect_cnsa_2_0 = expect(read_u8(rest)?)?;
    let expect_rfc_all_sets = expect(read_u8(rest)?)?;
    let pk_len = usize::from(read_u16(rest)?);
    let sig_len = usize::from(read_u16(rest)?);
    let msg_len = usize::from(read_u16(rest)?);
    Ok(Case {
        id,
        source,
        expect_default,
        expect_cnsa_2_0,
        expect_rfc_all_sets,
        pk: take(rest, pk_len)?,
        sig: take(rest, sig_len)?,
        msg: take(rest, msg_len)?,
    })
}

fn take<'a>(rest: &mut &'a [u8], n: usize) -> Result<&'a [u8], ParseError> {
    let (head, tail) = rest.split_at_checked(n).ok_or(ParseError::Truncated)?;
    *rest = tail;
    Ok(head)
}

fn read_u8(rest: &mut &[u8]) -> Result<u8, ParseError> {
    let [b] = take_array::<1>(rest)?;
    Ok(b)
}

fn read_u16(rest: &mut &[u8]) -> Result<u16, ParseError> {
    take_array(rest).map(u16::from_le_bytes)
}

fn take_array<const N: usize>(rest: &mut &[u8]) -> Result<[u8; N], ParseError> {
    <[u8; N]>::try_from(take(rest, N)?).map_err(|_| ParseError::Truncated)
}

/// A trusted-key set holding only `public_key` as an LMS/HSS key.
///
/// A key the set refuses (not 52 or 60 bytes, or failing
/// [`keelsign_verify::lms::check_public_key`]) is reported as [`Error::InvalidPublicKey`].
pub fn trusted_lms_key(public_key: &[u8]) -> Result<TrustedKeys<'_, 2>, Error> {
    TrustedKeys::new(&[TrustedKey {
        algorithm: Algorithm::LmsHss,
        public_key,
    }])
    .map_err(|_| Error::InvalidPublicKey)
}

/// The TLVs of an image carrying `signature` and the key-ID TLV `key_id`, between
/// MCUboot TLVs (KEYHASH, SHA256, ED25519) that the verifier must ignore.
pub fn image_tlvs<'a>(key_id: &'a [u8], signature: &'a [u8]) -> [(u16, &'a [u8]); 5] {
    const KEYHASH: [u8; 32] = [0x11; 32];
    const SHA256: [u8; 32] = [0x22; 32];
    const ED25519: [u8; 64] = [0x33; 64];
    [
        (0x0001, KEYHASH.as_slice()),
        (0x0010, SHA256.as_slice()),
        (TLV_KEELSIGN_KEY_ID, key_id),
        (0x0024, ED25519.as_slice()),
        (TLV_LMS_HSS_SIG, signature),
    ]
}

/// Verifies `case` on the device path: [`verify_pq`] (policy
/// [`ParameterPolicy::keelsign_default`]) with a trusted-key set holding the case's public
/// key, and TLVs carrying its key ID and signature.
#[inline(never)]
pub fn verify_case(case: &Case<'_>) -> Result<(), Error> {
    let keys = trusted_lms_key(case.pk)?;
    verify_with_keys(&keys, case)
}

/// [`verify_pq`] of `case`'s signature and message against `keys`, with TLVs carrying the
/// key ID of `case.pk`.
#[inline(never)]
pub fn verify_with_keys<const N: usize>(
    keys: &TrustedKeys<'_, N>,
    case: &Case<'_>,
) -> Result<(), Error> {
    let id = key_id_of(case.pk);
    verify_pq(keys, image_tlvs(&id, case.sig), case.msg).map(|_| ())
}

/// Verifies `case` on the strict device path: [`verify_pq_with`] with
/// [`DefaultBackend::cnsa_2_0`] (policy [`ParameterPolicy::cnsa_2_0`], single tree only),
/// a trusted-key set holding the case's public key, and TLVs carrying its key ID and
/// signature.
#[inline(never)]
pub fn verify_case_cnsa_2_0(case: &Case<'_>) -> Result<(), Error> {
    let keys = trusted_lms_key(case.pk)?;
    let id = key_id_of(case.pk);
    verify_pq_with(
        &DefaultBackend::cnsa_2_0(),
        &keys,
        image_tlvs(&id, case.sig),
        case.msg,
    )
    .map(|_| ())
}

/// Verifies `case` with [`lms::verify_with_policy`] under
/// [`ParameterPolicy::rfc_8554_all_sets`] (host and test use only).
pub fn verify_case_rfc_all_sets(case: &Case<'_>) -> Result<(), Error> {
    lms::verify_with_policy(
        &ParameterPolicy::rfc_8554_all_sets(),
        case.pk,
        case.msg,
        case.sig,
    )
}

/// The result of running one case under all three policies.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Outcome {
    pub id: u16,
    pub source: Source,
    pub expect_default: Expect,
    /// Result of [`verify_case`] (`keelsign_default()`).
    pub default: Result<(), Error>,
    pub expect_cnsa_2_0: Expect,
    /// Result of [`verify_case_cnsa_2_0`] (`cnsa_2_0()`).
    pub cnsa_2_0: Result<(), Error>,
    pub expect_rfc_all_sets: Expect,
    /// Result of [`verify_case_rfc_all_sets`].
    pub rfc_all_sets: Result<(), Error>,
}

impl Outcome {
    /// Runs `case` through [`verify_case`], [`verify_case_cnsa_2_0`] and
    /// [`verify_case_rfc_all_sets`].
    pub fn run(case: &Case<'_>) -> Self {
        Self {
            id: case.id,
            source: case.source,
            expect_default: case.expect_default,
            default: verify_case(case),
            expect_cnsa_2_0: case.expect_cnsa_2_0,
            cnsa_2_0: verify_case_cnsa_2_0(case),
            expect_rfc_all_sets: case.expect_rfc_all_sets,
            rfc_all_sets: verify_case_rfc_all_sets(case),
        }
    }

    /// True when all three results match their expectations.
    pub fn passed(&self) -> bool {
        self.default == self.expect_default.result()
            && self.cnsa_2_0 == self.expect_cnsa_2_0.result()
            && self.rfc_all_sets == self.expect_rfc_all_sets.result()
    }
}

/// Totals for a whole fixture run.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Summary {
    pub total: u32,
    pub passed: u32,
    /// The first case whose results did not match its expectations.
    pub first_failure: Option<Outcome>,
}

impl Summary {
    /// Records one outcome.
    pub fn record(&mut self, outcome: Outcome) {
        self.total = self.total.saturating_add(1);
        if outcome.passed() {
            self.passed = self.passed.saturating_add(1);
        } else if self.first_failure.is_none() {
            self.first_failure = Some(outcome);
        }
    }

    /// True when at least one case ran and every case matched its expectations.
    pub fn all_passed(&self) -> bool {
        self.total > 0 && self.passed == self.total
    }
}

/// Runs every case of the fixture `bytes`, calling `on_case` with each outcome.
pub fn run_fixture(
    bytes: &[u8],
    mut on_case: impl FnMut(&Case<'_>, &Outcome),
) -> Result<Summary, ParseError> {
    let fixture = Fixture::parse(bytes)?;
    let mut summary = Summary::default();
    for case in fixture.cases() {
        let case = case?;
        let outcome = Outcome::run(&case);
        on_case(&case, &outcome);
        summary.record(outcome);
    }
    Ok(summary)
}

/// The top-level parameters of a case's public key, for log labels.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct KeyInfo {
    /// Number of HSS levels `L`.
    pub levels: u32,
    /// LMS typecode of level 0.
    pub lms_typecode: u32,
    /// LM-OTS typecode of level 0.
    pub lmots_typecode: u32,
}

impl KeyInfo {
    /// Short name of the level-0 LMS parameter set, e.g. `M32_H5`.
    pub const fn lms_name(&self) -> &'static str {
        match self.lms_typecode {
            0x05 => "M32_H5",
            0x06 => "M32_H10",
            0x07 => "M32_H15",
            0x08 => "M32_H20",
            0x09 => "M32_H25",
            0x0A => "M24_H5",
            0x0B => "M24_H10",
            0x0C => "M24_H15",
            0x0D => "M24_H20",
            0x0E => "M24_H25",
            _ => "unknown",
        }
    }

    /// Short name of the level-0 LM-OTS parameter set, e.g. `W8`.
    pub const fn lmots_name(&self) -> &'static str {
        match self.lmots_typecode {
            0x01 | 0x05 => "W1",
            0x02 | 0x06 => "W2",
            0x03 | 0x07 => "W4",
            0x04 | 0x08 => "W8",
            _ => "unknown",
        }
    }

    /// Reads `L` and the level-0 typecodes from an HSS public key.
    pub fn of(public_key: &[u8]) -> Option<Self> {
        let mut rest = public_key;
        let mut next = || -> Option<u32> {
            let (head, tail) = rest.split_first_chunk::<4>()?;
            rest = tail;
            Some(u32::from_be_bytes(*head))
        };
        Some(Self {
            levels: next()?,
            lms_typecode: next()?,
            lmots_typecode: next()?,
        })
    }
}

/// The key-rotation check (SHA-171 TP3): with `a` and `b` signed by two different keys
/// over the same message,
/// - `b`'s image verifies against the set {A, B} and selects B;
/// - `b`'s image fails against the set {A} with [`Error::KeyNotTrusted`];
/// - `a`'s image verifies against {A, B} and selects A;
/// - `b`'s signature carrying A's key ID fails against {A, B} with
///   [`Error::SignatureInvalid`].
///
/// Every check goes through [`verify_pq`] ([`DefaultBackend::new`], the default policy).
pub fn check_rotation(a: &Case<'_>, b: &Case<'_>) -> Result<(), &'static str> {
    if a.msg != b.msg || a.pk == b.pk {
        return Err("rotation cases must sign the same message with different keys");
    }
    let key_a = TrustedKey {
        algorithm: Algorithm::LmsHss,
        public_key: a.pk,
    };
    let key_b = TrustedKey {
        algorithm: Algorithm::LmsHss,
        public_key: b.pk,
    };
    let both = TrustedKeys::<2>::new(&[key_a, key_b]).map_err(|_| "key set {A, B}")?;
    let a_only = TrustedKeys::<2>::new(&[key_a]).map_err(|_| "key set {A}")?;
    let id_a = key_id_of(a.pk);
    let id_b = key_id_of(b.pk);

    if verify_pq(&both, image_tlvs(&id_b, b.sig), b.msg) != Ok(key_b) {
        return Err("image signed with B must verify against {A, B} and select B");
    }
    if verify_pq(&a_only, image_tlvs(&id_b, b.sig), b.msg) != Err(Error::KeyNotTrusted) {
        return Err("image signed with B must fail against {A} with KeyNotTrusted");
    }
    if verify_pq(&both, image_tlvs(&id_a, a.sig), a.msg) != Ok(key_a) {
        return Err("image signed with A must verify against {A, B} and select A");
    }
    if verify_pq(&both, image_tlvs(&id_a, b.sig), b.msg) != Err(Error::SignatureInvalid) {
        return Err("B's signature under A's key ID must be SignatureInvalid");
    }
    Ok(())
}
